// Starting a trial with a farm already in it.
//
// Somebody evaluating this has about three minutes of patience, and an empty
// app answers none of the questions they came with. So a new account can start
// with a complete invented season — paddocks, silos with grain in them,
// contracts part delivered, a fert report with something to report — and
// delete it once they have seen enough.
//
// The data lives in docs/demo/seed.json, generated by tools/make-demo-seed.mjs
// and checked by tests/demo.test.mjs. Its ids are deliberately not UUIDs, so
// remapIds() reissues every one on import and two trial accounts never collide
// on a primary key.

import { DEFAULT_BUSINESS_DETAILS } from './import.js?v=90';
import { APP_VERSION } from './version.js?v=90';

const WANTED_KEY = 'grainflow.seedSample';

/** Remember, across the sign-up round trip, that they asked for sample data. */
export function wantSampleData() {
  try { sessionStorage.setItem(WANTED_KEY, '1'); } catch { /* private mode */ }
}

/**
 * Did they? Answering also forgets, because this must happen exactly once —
 * a flag left set would re-import the sample farm over the top of their real
 * work on the next sign-in.
 */
export function takeSampleDataRequest() {
  try {
    const wanted = sessionStorage.getItem(WANTED_KEY) === '1';
    sessionStorage.removeItem(WANTED_KEY);
    return wanted;
  } catch { return false; }
}

/**
 * The sample season, carrying the name they actually chose.
 *
 * The seed file has business details of its own — Kurrajong Downs Pty Ltd —
 * and importing it verbatim would push that straight over the farm name the
 * person typed thirty seconds earlier, because businessDetails.entityName is
 * what maps to farms.entity_name. They would name their farm and watch it
 * become somebody else's.
 *
 * So the sample's identity is dropped and theirs put in its place. Everything
 * else about the business details starts empty, which is also the honest
 * answer: those are the fields they need to fill in with their own, and a
 * plausible-looking ABN sitting there invites them not to.
 */
export function sampleStateFor(rawJson, farmName) {
  const state = JSON.parse(rawJson);
  const name = String(farmName || '').trim();
  state.businessDetails = {
    ...DEFAULT_BUSINESS_DETAILS,
    farmName: name,
    entityName: name,
    paymentTermsDays: 30,
  };
  return state;
}

/** Fetch the seed. Versioned so a device cannot be served last release's. */
export async function fetchSampleFarm(farmName) {
  const res = await fetch(`./demo/seed.json?v=${APP_VERSION}`, { cache: 'no-cache' });
  if (!res.ok) throw new Error(`sample data unavailable (${res.status})`);
  return sampleStateFor(await res.text(), farmName);
}
